{{pins}}
bool lightOn = false;
int lastButton = HIGH;

void setup() {
  pinMode(LED_PIN, OUTPUT);
  pinMode(BUTTON_PIN, INPUT_PULLUP);
}

void loop() {
  int button = digitalRead(BUTTON_PIN);
  // Just pressed: it was up last time and it's down now.
  if (button == LOW && lastButton == HIGH) {
    lightOn = !lightOn;
    digitalWrite(LED_PIN, lightOn ? HIGH : LOW);
    delay(50);  // let the button settle
  }
  lastButton = button;
}
